using System.IO;
using UnityEditor;
using UnityEngine;

namespace Parasite.EditorTools
{
    /// <summary>
    /// Import settings for the shared humanoid animation clips in Art/Characters/Animations (one FBX per clip,
    /// UAL skeleton, 30 fps, generated by Tools/blender/animation/build_animations.sh).
    /// Humanoid avatar from each file; clip named after the file; root rotation/height/XZ baked into the pose
    /// "based upon original", so clips are strictly in place and keep their authored body offsets (lying, sitting).
    /// Looping clips: names starting with "Idle_", ending in "_Loop", or Walk/Run(+_Possessed).
    /// FBX files under Animations/Preview are rest-pose preview mannequins (humanoid, no animation).
    /// </summary>
    public class HumanAnimationImporter : AssetPostprocessor
    {
        public const string Folder = "Assets/Parasite/Art/Characters/Animations/";
        public const string PreviewFolder = Folder + "Preview/";
        const uint Version = 3;

        public override uint GetVersion() => Version;

        static bool IsOurs(string path) =>
            path.StartsWith(Folder, System.StringComparison.Ordinal) && path.EndsWith(".fbx", System.StringComparison.OrdinalIgnoreCase);

        static bool IsPreview(string path) => path.StartsWith(PreviewFolder, System.StringComparison.Ordinal);

        public static bool IsLoop(string clip) =>
            clip.StartsWith("Idle_") || clip.EndsWith("_Loop") ||
            clip == "Walk" || clip == "Run" || clip == "Walk_Possessed" || clip == "Run_Possessed";

        void OnPreprocessModel()
        {
            if (!IsOurs(assetPath)) return;
            var mi = (ModelImporter)assetImporter;
            mi.globalScale = 1f;
            mi.useFileScale = true;
            mi.bakeAxisConversion = true;
            mi.importCameras = false;
            mi.importLights = false;
            mi.importVisibility = false;
            mi.importBlendShapes = false;
            mi.importConstraints = false;
            mi.animationType = ModelImporterAnimationType.Human;
            mi.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
            mi.optimizeGameObjects = false;
            if (IsPreview(assetPath))
            {
                mi.importAnimation = false;
                mi.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
                return;
            }
            mi.importAnimation = true;
            mi.materialImportMode = ModelImporterMaterialImportMode.None;
            mi.resampleCurves = true;
            mi.animationCompression = ModelImporterAnimationCompression.Optimal;
            mi.animationRotationError = 0.25f;
            mi.animationPositionError = 0.25f;
            mi.animationScaleError = 0.5f;
        }

        void OnPreprocessAnimation()
        {
            if (!IsOurs(assetPath) || IsPreview(assetPath)) return;
            var mi = (ModelImporter)assetImporter;
            var defs = mi.defaultClipAnimations;
            if (defs == null || defs.Length == 0)
            {
                Debug.LogWarning($"[Anim] {assetPath}: no animation take found");
                return;
            }
            string name = Path.GetFileNameWithoutExtension(assetPath);
            bool loop = IsLoop(name);
            var c = defs[0];
            c.name = name;
            c.loopTime = loop;
            c.loopPose = loop;
            c.cycleOffset = 0f;
            c.lockRootRotation = true;
            c.keepOriginalOrientation = true;
            c.lockRootHeightY = true;
            c.keepOriginalPositionY = true;
            c.heightFromFeet = false;
            c.lockRootPositionXZ = true;
            c.keepOriginalPositionXZ = true;
            c.heightOffset = 0f;
            c.rotationOffset = 0f;
            c.mirror = false;
            c.hasAdditiveReferencePose = false;
            mi.clipAnimations = new[] { c };
        }
    }
}
